//! Macro PDF417 (ISO 15438 Annex H): decode Okapi Barcode's specimens
//! (generated by /tmp oracle Gen.java, extracted via examples/cwprobe
//! through stream::read_exact) and round-trip our own encoder against
//! the independent zxing-cpp reader (verified in-session, 12/12 with
//! full metadata; see docs/STATUS.md macro block).

use barcode_pdf417::encode::{encode_macro_full, MacroFields, DEFAULT_LEVEL};

/// label -> expected payload text of each okapi specimen.
const EXPECTED: &[(&str, &[u8])] = &[
    ("m1_min", b"hello"),
    ("m2_name", b"hello"),
    ("m3_namecount", b"hello"),
    ("m4_id7_pos0", b"A"),
    ("m5_digits", b"12345678901234567890"),
    ("m6_bytes", &[0x00, 0x01, 0xFF, 0xFE, b'x']),
    ("m7_plain", b"hello"),
    ("m8_solo", b"solo"),
    ("m9_extremes", b"data"),
];

fn specimens() -> Vec<(String, Vec<Vec<u8>>)> {
    let text = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/testdata/okapi_macro_truth.txt"
    ))
    .unwrap();
    let mut out = Vec::new();
    let mut label = String::new();
    let mut rows = Vec::new();
    let flush = |label: &str, rows: &mut Vec<Vec<u8>>, out: &mut Vec<(String, Vec<Vec<u8>>)>| {
        if !rows.is_empty() {
            out.push((label.to_string(), std::mem::take(rows)));
        }
    };
    for line in text.lines() {
        if let Some(rest) = line.strip_prefix("SYM ") {
            flush(&label, &mut rows, &mut out);
            label = rest.trim().to_string();
        } else if line.starts_with('#') {
            rows.push(line.bytes().map(|b| (b == b'#') as u8).collect());
        }
    }
    flush(&label, &mut rows, &mut out);
    out
}

/// Every Okapi specimen (macro and plain) decodes to its payload.
#[test]
fn okapi_specimens_decode() {
    let all = specimens();
    assert_eq!(all.len(), EXPECTED.len(), "specimen set changed");
    for (label, rows) in &all {
        let expected = &EXPECTED.iter().find(|(l, _)| l == label).unwrap().1;
        let h = rows.len();
        let w = rows[0].len();
        let flat: Vec<u8> = rows.iter().flatten().copied().collect();
        assert_eq!(
            barcode_pdf417::decode_exact(&flat, w, h).as_deref(),
            Some(*expected),
            "{label}: payload mismatch"
        );
    }
}

fn round_trip(payload: &[u8], m: MacroFields) {
    let sym = encode_macro_full(&m, payload, DEFAULT_LEVEL).unwrap();
    assert_eq!(
        barcode_pdf417::decode_exact(&sym.matrix, sym.width, sym.height).as_deref(),
        Some(payload),
        "idx {} last {} fid {:?}",
        m.segment_index,
        m.last,
        m.file_id
    );
}

/// Our encoder round-trips across the spec's boundaries (index 0/99998,
/// count 1/99999, empty-to-max file IDs, all optional field types).
#[test]
fn macro_round_trips() {
    round_trip(
        b"hello",
        MacroFields {
            segment_index: 0,
            file_id: &[123],
            last: false,
            file_name: None,
            sender: None,
            addressee: None,
            segment_count: None,
            timestamp: None,
            file_size: None,
            checksum: None,
        },
    );
    round_trip(
        b"hello",
        MacroFields {
            segment_index: 1,
            file_id: &[123],
            last: true,
            file_name: Some("name.txt"),
            sender: None,
            addressee: None,
            segment_count: Some(2),
            timestamp: None,
            file_size: None,
            checksum: None,
        },
    );
    round_trip(
        b"A",
        MacroFields {
            segment_index: 0,
            file_id: &[7],
            last: false,
            file_name: None,
            sender: None,
            addressee: None,
            segment_count: None,
            timestamp: None,
            file_size: None,
            checksum: None,
        },
    );
    round_trip(
        b"12345678901234567890",
        MacroFields {
            segment_index: 1,
            file_id: &[42],
            last: false,
            file_name: None,
            sender: None,
            addressee: None,
            segment_count: None,
            timestamp: None,
            file_size: None,
            checksum: None,
        },
    );
    round_trip(
        b"solo",
        MacroFields {
            segment_index: 0,
            file_id: &[9],
            last: true,
            file_name: Some("solo.bin"),
            sender: None,
            addressee: None,
            segment_count: Some(1),
            timestamp: None,
            file_size: None,
            checksum: None,
        },
    );
    round_trip(
        b"data",
        MacroFields {
            segment_index: 99997,
            file_id: &[899],
            last: false,
            file_name: Some("a-very-long-file-name-example.txt"),
            sender: None,
            addressee: None,
            segment_count: None,
            timestamp: None,
            file_size: None,
            checksum: None,
        },
    );
    round_trip(
        b"meta",
        MacroFields {
            segment_index: 0,
            file_id: &[5],
            last: true,
            file_name: Some("f.bin"),
            sender: None,
            addressee: None,
            segment_count: Some(3),
            timestamp: Some(1767225000),
            file_size: Some(1234),
            checksum: Some(4711),
        },
    );
    round_trip(
        &[0x00u8, 0x01, 0xFF, 0xFE],
        MacroFields {
            segment_index: 99998,
            file_id: &[0, 899],
            last: true,
            file_name: Some("z"),
            sender: None,
            addressee: None,
            segment_count: Some(99999),
            timestamp: Some(4102444800),
            file_size: Some(68719476735),
            checksum: Some(65535),
        },
    );
    // sender + addressee (H.4's own example strings) alongside every
    // other optional field, over a binary payload
    round_trip(
        &[0x00u8, 0x01, 0xFF, 0xFE],
        MacroFields {
            segment_index: 2,
            file_id: &[0, 899],
            last: false,
            file_name: Some("z"),
            sender: Some("cen be"),
            addressee: Some("iso ch"),
            segment_count: Some(99999),
            timestamp: Some(4102444800),
            file_size: Some(68719476735),
            checksum: Some(65535),
        },
    );
}

/// ISO 15438 H.4's worked example is the only oracle for sender/
/// addressee (Okapi has no such setters): symbol 1 of 4 carries
/// [928][111 100][017 053][923 1][111 104][923 3][64 416 34]
/// [923 4][258 446 67] — segment count 4, sender "cen be",
/// addressee "iso ch", all in implied TC-Alpha (lowercase in the
/// spec's PDF). The last segment's block is [928][111 103][017 053]
/// [923 1][111 104][922].
#[test]
fn control_block_matches_h4_example() {
    let first = encode_macro_full(
        &MacroFields {
            segment_index: 0,
            file_id: &[17, 53],
            last: false,
            file_name: None,
            sender: Some("cen be"),
            addressee: Some("iso ch"),
            segment_count: Some(4),
            timestamp: None,
            file_size: None,
            checksum: None,
        },
        b"hello",
        DEFAULT_LEVEL,
    )
    .unwrap();
    let stream =
        barcode_pdf417::stream::read_exact(&first.matrix, first.width, first.height).unwrap();
    let (_, data, _) = barcode_pdf417::stream::split_stream(&stream).unwrap();
    let data = barcode_pdf417::stream::strip_pads(data);
    let cb = &[
        928, 111, 100, 17, 53, 923, 1, 111, 104, 923, 3, 64, 416, 34, 923, 4, 258, 446, 67,
    ];
    assert_eq!(
        &data[data.len() - cb.len()..],
        cb,
        "H.4 first-segment block mismatch"
    );

    let last = encode_macro_full(
        &MacroFields {
            segment_index: 3,
            file_id: &[17, 53],
            last: true,
            file_name: None,
            sender: None,
            addressee: None,
            segment_count: Some(4),
            timestamp: None,
            file_size: None,
            checksum: None,
        },
        b"hello",
        DEFAULT_LEVEL,
    )
    .unwrap();
    let stream = barcode_pdf417::stream::read_exact(&last.matrix, last.width, last.height).unwrap();
    let (_, data, _) = barcode_pdf417::stream::split_stream(&stream).unwrap();
    let data = barcode_pdf417::stream::strip_pads(data);
    let cb = &[928, 111, 103, 17, 53, 923, 1, 111, 104, 922];
    assert_eq!(
        &data[data.len() - cb.len()..],
        cb,
        "H.4 last-segment block mismatch"
    );
}

/// The m2 configuration's control block must equal Okapi's codeword for
/// codeword: [928][111 100][123][923 0][TC("name.txt")].
#[test]
fn control_block_matches_okapi() {
    let sym = encode_macro_full(
        &MacroFields {
            segment_index: 0,
            file_id: &[123],
            last: false,
            file_name: Some("name.txt"),
            sender: None,
            addressee: None,
            segment_count: None,
            timestamp: None,
            file_size: None,
            checksum: None,
        },
        b"hello",
        DEFAULT_LEVEL,
    )
    .unwrap();
    let stream = barcode_pdf417::stream::read_exact(&sym.matrix, sym.width, sym.height).unwrap();
    let (desc, data, _) = barcode_pdf417::stream::split_stream(&stream).unwrap();
    let data = barcode_pdf417::stream::strip_pads(data);
    let cb = &[928, 111, 100, 123, 923, 0, 823, 12, 149, 529, 709];
    assert_eq!(&data[data.len() - cb.len()..], cb, "control block mismatch");
    // everything before the block is the payload TC stream + 900 pads
    let prefix = &data[..data.len() - cb.len()];
    assert_eq!(
        prefix[..3],
        [817, 131, 344],
        "payload TC stream must precede the block"
    );
    assert!(
        prefix[3..].iter().all(|&v| v == 900),
        "only pad latches allowed before the block"
    );
    assert_eq!(desc as usize, data.len() + 1, "descriptor counts the block");
}
